import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    answer = 0
    idx = 2

    for _ in range(m):
        u, v = data[idx], data[idx + 1]
        idx += 2

        ru = find(u)
        rv = find(v)

        if ru == rv:
            answer += 1
        else:
            if size[ru] < size[rv]:
                ru, rv = rv, ru
            parent[rv] = ru
            size[ru] += size[rv]

    print(answer)

if __name__ == "__main__":
    solve()
